using System;using System.IO;using System.Collections.Generic;using System.Runtime.InteropServices;using SolidWorks.Interop.sldworks;
public static class SwReadMotorContext{
 static object[] A(object x){return x as object[]??new object[0];}
 static double[] Read(IModelDoc2 doc,bool selected,string label){int status=0;Console.WriteLine("READ_MASS "+label);double[] x=doc.Extension.GetMassProperties2(1,out status,selected) as double[];if(status!=0||x==null||x.Length<12)throw new Exception("Mass read failed "+label+" status="+status);return x;}
 static bool Hip(string n){return(n.StartsWith("8009-RAU_5005_",StringComparison.OrdinalIgnoreCase)||n.StartsWith("Mirror8009-RAU_5005_",StringComparison.OrdinalIgnoreCase))&&n.EndsWith(".SLDASM",StringComparison.OrdinalIgnoreCase);}
 static bool Wheel(string n){return String.Equals(n,"DM-S3519-1EC_3d-250509.SLDASM",StringComparison.OrdinalIgnoreCase)||String.Equals(n,"MirrorDM-S3519-1EC_3d-250509.SLDASM",StringComparison.OrdinalIgnoreCase);}
 public static object Run(string expected){ISldWorks sw=(ISldWorks)Marshal.GetActiveObject("SldWorks.Application");IModelDoc2 d=sw.ActiveDoc as IModelDoc2;if(d==null||!String.Equals(d.GetPathName(),expected,StringComparison.OrdinalIgnoreCase))throw new Exception("Task assembly is not active; no selection changed");var r=new Dictionary<string,object>();r["assembly_path"]=expected;r["configuration"]=d.ConfigurationManager.ActiveConfiguration.Name;r["started_utc"]=DateTime.UtcNow.ToString("o");IAssemblyDoc a=(IAssemblyDoc)d;var units=new List<IComponent2>();int nh=0,nw=0;foreach(IComponent2 c in A(a.GetComponents(false))){if(c.GetSuppression()==0)continue;string n=Path.GetFileName(c.GetPathName());if(Hip(n)){units.Add(c);nh++;}else if(Wheel(n)){units.Add(c);nw++;}}if(nh!=4||nw!=2)throw new Exception("Expected4hip and2wheel motor instances");var results=new List<object>();try{d.ClearSelection2(true);r["root_mass_properties_si"]=Read(d,false,"whole assembly");foreach(IComponent2 c in units){d.ClearSelection2(true);if(c.GetSuppression()==1)c.SetSuppression2(2);if(!c.Select4(false,null,false))throw new Exception("Motor selection failed: "+c.Name2);string n=Path.GetFileName(c.GetPathName());var item=new Dictionary<string,object>();item["component"]=c.Name2;item["path"]=c.GetPathName();item["configuration"]=c.ReferencedConfiguration;item["is_virtual"]=c.IsVirtual;item["is_hip"]=Hip(n);item["target_mass_kg"]=Hip(n)?0.963:0.131;item["target_source"]=Hip(n)?"Exact OEM module manualV1.3 corrected963g":"Human supplied131g per retained bare motor after reducer removal";item["selected_component_mass_properties_si"]=Read(d,true,c.Name2);IModelDoc2 m=c.GetModelDoc2() as IModelDoc2;if(m!=null){item["model_document_path"]=m.GetPathName();item["model_read_only"]=m.IsOpenedReadOnly();item["model_dirty"]=m.GetSaveFlag();}var p=c.GetParent();if(p!=null){item["parent_component"]=p.Name2;item["parent_path"]=p.GetPathName();}results.Add(item);}d.ClearSelection2(true);foreach(IComponent2 c in units)if(!c.Select4(true,null,false))throw new Exception("Motor combined selection failed");r["all_selected_motors_mass_properties_si"]=Read(d,true,"all6motors");r["motor_instances"]=results;r["motor_count"]=units.Count;r["geometry_edit_calls"]=0;r["CAD_mass_override_setter_calls"]=0;r["CAD_save_calls"]=0;r["finished_utc"]=DateTime.UtcNow.ToString("o");}finally{d.ClearSelection2(true);}return r;}
}
